sys_script_client.script:
function onLoad() {
    var pendingTelco = g_form.getValue('x_g_sonc_ns_pro_pending_telco_provider');
    var pendingHostCircuit = g_form.getValue('x_g_sonc_ns_pro_pending_pe_host_circuit_id');


    var circuitInformation = {};
    circuitInformation.sys_id = g_form.getUniqueValue();
    circuitInformation.site = g_form.getValue('x_g_sonc_ns_pro_site');
    g_scratchpad.circuitInformation = circuitInformation;
    if (pendingTelco) {
        if (!pendingHostCircuit) {
            g_form.setMandatory('x_g_sonc_ns_pro_pending_pe_host_circuit_id', true);

        }
    }


}
